     1	// What a policy costs. This module answers one question — given the items on
     2	// a policy and the context the policy is written in, what premium does the
     3	// customer pay? It knows nothing about scenarios, steps, or the order events
     4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
     5	// mirror question, answered by coverage.ts.
     6	
     7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
     8	import { quoteRejection } from "./rejection.js";
     9	
    10	export interface Customer {
    11	  yearsWithMHPCO: number;
    12	}
    13	
    14	const PROCESSING_FEE = 5;
    15	const BASE_PREMIUM_BY_TYPE = {
    16	  sword: 100,
    17	  amulet: 60,
    18	  staff: 80,
    19	  potion: 40,
    20	  rune: 25,
    21	  moonstone: 25,
    22	} as const satisfies Record<string, number>;
    23	
    24	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
    25	
    26	export interface Item {
    27	  type: KnownItemType;
    28	  material?: string;
    29	  enchantment?: number;
    30	  cursed?: boolean;
    31	}
    32	
    33	const FIRST_INSURANCE_SURCHARGE = 0.1;
    34	
    35	// The MHPCO's price list is closed: an item whose type is absent from it has
    36	// no premium and no insurance value, so the quote is refused rather than
    37	// guessed at. The type reaches here from parsed JSON, so the compiler's
    38	// KnownItemType narrowing is not enough on its own.
    39	const basePremiumOf = (item: Item): number => {
    40	  const basePremium: number | undefined = BASE_PREMIUM_BY_TYPE[item.type];
    41	  if (basePremium === undefined) {
    42	    throw quoteRejection(
    43	      `names a ${item.type}, which the MHPCO does not insure`,
    44	    );
    45	  }
    46	  return basePremium;
    47	};
    48	
    49	const BLOCK_SIZE = 3;
    50	const BLOCK_BASE_PREMIUM = 60;
    51	
    52	const groupByType = (items: Item[]): Item[][] => [
    53	  ...items
    54	    .reduce(
    55	      (groups, item) =>
    56	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
    57	      new Map<KnownItemType, Item[]>(),
    58	    )
    59	    .values(),
    60	];
    61	
    62	const sumOfBasePremiums = (items: Item[]): number =>
    63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
    64	
    65	// Exactly three alike components form a block at a reduced premium; any
    66	// other count is priced per item.
    67	//
    68	// Deliberate simplification: "component" is not yet enforced, so three alike
    69	// swords would also get the block. No test covers it and the spec gives no
    70	// example — revisit when one does.
    71	const groupBasePremiumOf = (group: Item[]): number =>
    72	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
    73	
    74	const policyBasePremiumOf = (items: Item[]): number =>
    75	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
    76	
    77	const CURSE_SURCHARGE = 0.5;
    78	
    79	// Item-specific modifiers are charged as a percentage of the affected item's
    80	// OWN base premium. See withPolicyWideModifiers for the other scope.
    81	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
    82	  basePremiumOf(item) * rate;
    83	
    84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
    85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
    86	
    87	const isHighlyEnchanted = (item: Item): boolean =>
    88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
    89	
    90	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
    91	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
    92	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
    93	];
    94	
    95	// Every modifier rate in this domain combines additively, whether item-scoped
    96	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
    97	const combinedRate = (rates: number[]): number =>
    98	  rates.reduce((total, rate) => total + rate, 0);
    99	
   100	// Both item modifiers can apply at once, and they stack additively: a cursed
   101	// item with enchantment 5 pays 50 % + 30 % of its base premium.
   102	const surchargeRateOn = (item: Item): number =>
   103	  combinedRate(
   104	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
   105	      ({ rate }) => rate,
   106	    ),
   107	  );
   108	
   109	const surchargeOn = (item: Item): number =>
   110	  shareOfOwnBasePremium(item, surchargeRateOn(item));
   111	
   112	const itemSurchargesOf = (items: Item[]): number =>
   113	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
   114	
   115	// Policy-wide modifiers scale the whole policy base premium, unlike item
   116	// modifiers which are charged against the affected item's own base premium.
   117	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
   118	// its base — not 110 % × 80 %.
   119	const LOYALTY_DISCOUNT = -0.2;
   120	const LOYALTY_THRESHOLD_YEARS = 2;
   121	
   122	const isLoyal = (customer: Customer): boolean =>
   123	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
   124	
   125	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
   126	
   127	// Everything about the policy's context that shifts its rates, as opposed to
   128	// the items being priced. Travels as one value because every policy-wide
   129	// modifier reads from it.
   130	export interface PolicyContext {
   131	  customer: Customer;
   132	  isFollowUpContract: boolean;
   133	}
   134	
   135	const policyWideModifierRatesFor = ({
   136	  customer,
   137	  isFollowUpContract,
   138	}: PolicyContext): number[] => [
   139	  FIRST_INSURANCE_SURCHARGE,
   140	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
   141	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
   142	];
   143	
   144	const withPolicyWideModifiers = (
   145	  policyBase: number,
   146	  policy: PolicyContext,
   147	): number =>
   148	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
   149	
   150	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
   151	  roundUpInFavourOfMHPCO(
   152	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
   153	      itemSurchargesOf(items) +
   154	      PROCESSING_FEE,
   155	  );
===== src/coverage.ts =====
     1	// What a policy covers, and what it pays out. The mirror image of pricing.ts:
     2	// that module answers what the customer pays us, this one answers what we pay
     3	// the customer. Both are asked by claim-office.ts, which knows the order the
     4	// questions come in; neither knows anything about scenarios or steps.
     5	
     6	import { type Item, type KnownItemType } from "./pricing.js";
     7	import { roundDownInFavourOfMHPCO } from "./rounding.js";
     8	import { claimRejection } from "./rejection.js";
     9	
    10	export interface Damage {
    11	  itemType: string;
    12	  amount: number;
    13	}
    14	
    15	// What an item is insured FOR, as opposed to what insuring it costs. Payout
    16	// caps are derived from these; premiums are not.
    17	//
    18	// Deliberately typed as a TOTAL Record over KnownItemType, and deliberately
    19	// looked up UNGUARDED below, unlike the price list in pricing.ts. Two reasons,
    20	// and the type is the load-bearing one:
    21	//
    22	//  - Adding a type to pricing.ts's BASE_PREMIUM_BY_TYPE without adding it here
    23	//    is a compile error, so the two tables cannot drift apart silently. The
    24	//    price list needs its runtime guard because item types arrive from parsed
    25	//    JSON and can be values TypeScript never saw; this table is only ever
    26	//    indexed by a type that already survived that guard.
    27	//  - A quote is rejected before any policy exists, so no unknown type can
    28	//    reach a cap. A throw here would be a branch no test could turn red.
    29	const INSURANCE_VALUE_BY_TYPE: Record<KnownItemType, number> = {
    30	  sword: 1000,
    31	  amulet: 600,
    32	  staff: 800,
    33	  potion: 400,
    34	  rune: 250,
    35	  moonstone: 250,
    36	};
    37	
    38	const insuranceSumOf = (items: Item[]): number =>
    39	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
    40	
    41	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    42	
    43	// A policy pays out at most twice what its items are insured for. Premium
    44	// modifiers — curses, enchantments, block discounts — shift what the policy
    45	// COSTS and never what it COVERS, so the cap reads insurance values only.
    46	export const capFor = (items: Item[]): number =>
    47	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
    48	
    49	// What a claim actually pays, once the policy's own limit is consulted. The
    50	// cap is a running total: a policy pays out at most twice its insurance sum
    51	// ACROSS all its claims, so each settlement both reads the cap left to it and
    52	// reports what remains for the next one.
    53	//
    54	// Lives here beside capFor rather than in the orchestrator: establishing the
    55	// limit and enforcing it are one rule, and claim-office.ts is only meant to
    56	// know the order the questions come in, not the answers.
    57	export interface Settlement {
    58	  payout: number;
    59	  remainingCap: number;
    60	}
    61	
    62	// Settling is where the damages stop being a running calculation and become
    63	// money, so it is where the payout is rounded — down, in the MHPCO's favour.
    64	// Rounding here rather than afterwards also keeps the cap whole: what leaves
    65	// the cap is exactly what the customer is paid.
    66	export const settleClaim = (
    67	  grossPayout: number,
    68	  remainingCap: number,
    69	): Settlement => {
    70	  const payout = roundDownInFavourOfMHPCO(Math.min(grossPayout, remainingCap));
    71	  return { payout, remainingCap: remainingCap - payout };
    72	};
    73	
    74	const DEDUCTIBLE_PER_DAMAGE = 100;
    75	
    76	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
    77	const HALF_REIMBURSEMENT_SHARE = 0.5;
    78	
    79	const FULL_REIMBURSEMENT_SHARE = 1;
    80	
    81	// Named for the clause it gates rather than for a degree of enchantment:
    82	// pricing.ts has its own, LOWER enchantment threshold (>= 5, a premium
    83	// surcharge), and the two are easy to confuse when both read as adjectives.
    84	const qualifiesForHalfReimbursement = (item: Item): boolean =>
    85	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
    86	
    87	// The reimbursement clauses in the order the MHPCO applies them: the FIRST
    88	// matching clause decides the share, later ones never override it. Order is
    89	// the whole content of the rule, which is why this stays a list of one rather
    90	// than collapsing into the conditional it currently is — the next clause the
    91	// spec forces is appended here, and its position is the decision.
    92	//
    93	// A clause matching NOTHING falls through to FULL_REIMBURSEMENT_SHARE below.
    94	// That default is deliberately NOT written as a catch-all clause at the end of
    95	// this list: a catch-all makes the `find` total, which in turn makes the `??`
    96	// that expresses the default unreachable, so the same "full unless stated
    97	// otherwise" rule ends up stated twice and one of the two statements is dead.
    98	//
    99	// Half reimbursement: the MHPCO holds that a strongly enchanted item's magic
   100	// bears part of its own misfortune.
   101	const REIMBURSEMENT_CLAUSES: {
   102	  applies: (item: Item) => boolean;
   103	  share: number;
   104	}[] = [
   105	  { applies: qualifiesForHalfReimbursement, share: HALF_REIMBURSEMENT_SHARE },
   106	];
   107	
   108	// Deliberately ABSENT: the spec's "dragon material => full reimbursement"
   109	// clause, which would sit above the half clause. It is unwritten because it is
   110	// untestable from the spec's examples — full reimbursement is also the default,
   111	// so every dragon example yields the same payout with or without it. The one
   112	// case that WOULD distinguish the two orderings, a dragon item with
   113	// enchantment >= 8, is fixed by example at HALF (see the enchantment-9 test),
   114	// which is the opposite of what a dragon-first clause would pay. So the spec's
   115	// own examples contradict placing a dragon clause first, and no example
   116	// justifies placing it anywhere else. Adding one here would be guesswork
   117	// dressed as fidelity; `material` stays unread until an example forces it.
   118	
   119	const reimbursementShareFor = (item: Item): number =>
   120	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.share ??
   121	  FULL_REIMBURSEMENT_SHARE;
   122	
   123	const reimbursementFor = (item: Item, damage: Damage): number =>
   124	  damage.amount * reimbursementShareFor(item);
   125	
   126	// The customer bears the first 100 G of each damage entry separately, so two
   127	// damaged swords carry two deductibles rather than one. The deductible comes
   128	// off AFTER the reimbursement clauses have reduced the amount.
   129	//
   130	// Named for the single subtraction it performs, not for the final payout: this
   131	// result is not floored at zero, and the policy's remaining cap is applied
   132	// later by settleClaim rather than here. Flooring is still it.todo() in the
   133	// spec ("exhausts the cap across successive claims"); until an example forces
   134	// it, the name must not claim a settlement this does not compute.
   135	const netOfDeductible = (item: Item, damage: Damage): number =>
   136	  reimbursementFor(item, damage) - DEDUCTIBLE_PER_DAMAGE;
   137	
   138	// Two different ways a damage can fail to find an insured item, which the
   139	// MHPCO rejects for two different reasons. A policy that insures no amulet at
   140	// all does not "cover more amulet damages than it insures" — it covers none,
   141	// and the claim names an item the customer never brought in. Telling them
   142	// apart needs the policy's ORIGINAL items, not just the ones still unclaimed.
   143	const uninsuredTypeError = (itemType: string): Error =>
   144	  claimRejection(`names a ${itemType}, which the policy does not insure`);
   145	
   146	const overClaimedTypeError = (itemType: string): Error =>
   147	  claimRejection(`covers more ${itemType} damages than the policy insures`);
   148	
   149	const unmatchedDamageError = (insured: Item[], itemType: string): Error =>
   150	  insured.some((item) => item.type === itemType)
   151	    ? overClaimedTypeError(itemType)
   152	    : uninsuredTypeError(itemType);
   153	
   154	// Which insured item a damage entry is paid against. A damage names its item
   155	// by type only, so the first insured item of that type answers it — but each
   156	// insured item is damaged at most once per claim, so a matched item is removed
   157	// from those still available. Two sword damages need two insured swords.
   158	const takeDamagedItem = (
   159	  insured: Item[],
   160	  available: Item[],
   161	  damage: Damage,
   162	): { item: Item; remaining: Item[] } => {
   163	  const index = available.findIndex((item) => item.type === damage.itemType);
   164	  if (index === -1) {
   165	    throw unmatchedDamageError(insured, damage.itemType);
   166	  }
   167	  return {
   168	    item: available[index],
   169	    remaining: available.filter((_, at) => at !== index),
   170	  };
   171	};
   172	
   173	// Each damage paired with the insured item it is settled against. Separated
   174	// from the summing below because pairing and arithmetic are two rules: which
   175	// item answers a damage is a matching question, what that pair pays is not.
   176	// This is also where an unmatched damage is rejected, so payoutForDamages sees
   177	// only pairs it can price.
   178	interface SettledPair {
   179	  item: Item;
   180	  damage: Damage;
   181	}
   182	
   183	const pairDamagesWithItems = (
   184	  items: Item[],
   185	  damages: Damage[],
   186	): SettledPair[] =>
   187	  damages.reduce<{ pairs: SettledPair[]; available: Item[] }>(
   188	    ({ pairs, available }, damage) => {
   189	      const { item, remaining } = takeDamagedItem(items, available, damage);
   190	      return { pairs: [...pairs, { item, damage }], available: remaining };
   191	    },
   192	    { pairs: [], available: items },
   193	  ).pairs;
   194	
   195	// A damage is a loss, never a gain: a negative amount would pay the MHPCO's
   196	// own money back into the policy's cap, so the claim is rejected outright.
   197	const rejectNegativeAmounts = (damages: Damage[]): void => {
   198	  for (const { itemType, amount } of damages) {
   199	    if (amount < 0) {
   200	      throw claimRejection(
   201	        `reports a negative ${itemType} damage of ${amount}`,
   202	      );
   203	    }
   204	  }
   205	};
   206	
   207	export const payoutForDamages = (items: Item[], damages: Damage[]): number => {
   208	  rejectNegativeAmounts(damages);
   209	  return pairDamagesWithItems(items, damages).reduce(
   210	    (total, { item, damage }) => total + netOfDeductible(item, damage),
   211	    0,
   212	  );
   213	};
===== src/rejection.ts =====
     1	// How the MHPCO refuses paperwork. Every refusal reads the same way: the kind
     2	// of document being refused, then what is wrong with it — "claim reports a
     3	// negative sword damage of -5", "quote names a broomstick, which the MHPCO
     4	// does not insure".
     5	//
     6	// The convention lives here rather than at each throw site because the two
     7	// documents are refused from two different modules — a quote from pricing.ts,
     8	// a claim from coverage.ts — and neither is the natural owner of the other's
     9	// wording. Keeping the shape in one place is what stops the third rejection
    10	// from inventing a third phrasing.
    11	
    12	const rejectionOf =
    13	  (document: string) =>
    14	  (reason: string): Error =>
